import React,{useState} from 'react';import {createRoot} from 'react-dom/client';
import {CreatorRollBridge} from '../../apps/room3d/chibi/CreatorRollBridge';import {decodeParts,createVisitor} from '../../apps/room3d/chibi/visitor';import {mountHomeEditor} from '../../apps/room3d/editor.js';import {bathroomHome} from './bathroom-layout.js';import '../../apps/room3d/editor.css';
function Fixture(){const [request,setRequest]=useState(0);return <><div id="home"/><CreatorRollBridge request={request} onReady={()=>setRequest(1)} onError={console.error} onResult={async result=>{const w=window as any;if(w.__loading)return;w.__loading=true;const c=await fetch('/room3d/catalog.json').then(r=>r.json()),key='bathroom-edge-actions-1',home=JSON.parse(localStorage.getItem(key)||'null')||bathroomHome(c);if(new URLSearchParams(location.search).has('empty')&&!localStorage.getItem(key))home.rooms[0].items=[];const e=await mountHomeEditor(document.querySelector('#home')!,{assetBase:new URL('/room3d/',location.href).href,initialState:home,storageKey:key});const visitor=await createVisitor(await decodeParts(result));e.setVisitor!(visitor);w.__visitor=visitor;w.__homeEditor=e;w.render_game_to_text=()=>JSON.stringify(e.inspect!());w.advanceTime=(ms:number)=>e.advanceTime!(ms);if(new URLSearchParams(location.search).has('panel'))(document.querySelector('[data-panel="chibi"]') as HTMLButtonElement).click();}}/></>;}createRoot(document.querySelector('#root')!).render(<Fixture/>);
